import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import path from 'path';
import type { RequestHandler } from 'express';
import * as sea from 'node:sea';

// In the exe built by scripts/compile.ts (Node SEA), each embedded asset folder (build/public,
// audify's build/Release) is baked into the binary as a flat set of "<folder>/<relPath>" asset
// keys (see sea-config.json, generated by scripts/build-sea-assets.ts). node:sea has no
// directory-listing API of its own, so getAssetKeys() stands in for a readdir. Under plain
// `node build/index.js` nothing is embedded - sea.isSea() is false, same as "Under `bun run`
// nothing is embedded" for the Bun version this replaces.
export const isCompiled = sea.isSea();

// Kept for interface parity with the Bun version; nothing else in this codebase reads it -
// Node SEA assets live inside the binary itself, not at a real path next to it.
export const embeddedRoot = isCompiled ? path.dirname(process.execPath) : '';

let assetKeys: Set<string> | null = null;
function keys(): Set<string> {
    if (!assetKeys) assetKeys = new Set(sea.getAssetKeys());
    return assetKeys;
}

// Copies an embedded folder to a real folder on disk, skipping files that are already
// identical (a running copy of the exe may hold them open).
export function writeEmbeddedFolder(name: string, dest: string) {
    mkdirSync(dest, { recursive: true });
    const prefix = `${name}/`;
    for (const key of keys()) {
        if (!key.startsWith(prefix)) continue;
        const file = key.slice(prefix.length);
        const data = Buffer.from(sea.getAsset(key));
        const out = path.join(dest, file);
        mkdirSync(path.dirname(out), { recursive: true });
        if (existsSync(out) && readFileSync(out).equals(data)) continue;
        writeFileSync(out, data);
    }
}

// express.static streams files with ranged read streams, which reset the connection for files
// baked into a Bun exe; the same problem applies to data pulled out of a Node SEA binary, which
// isn't a real file at all. This serves an embedded folder from memory instead.
export function embeddedStatic(name: string): RequestHandler {
    const prefix = `${name}/`;
    return (req, res, next) => {
        if (req.method !== 'GET' && req.method !== 'HEAD') return next();
        let rel: string;
        try { rel = decodeURIComponent(req.path); } catch { return next(); }
        if (rel.endsWith('/')) rel += 'index.html';
        const key = path.posix.normalize(prefix + rel);
        if (!key.startsWith(prefix) || !keys().has(key)) return next();
        const data = Buffer.from(sea.getAsset(key));
        res.type(path.extname(key)).send(data);
    };
}
